(function(){var c=document.getElementById('previo-booking-engine');if(!c)return;var id=c.getAttribute('data-previo-id');if(!id)return;window.bookingEngineConfig={id:id,lang:c.getAttribute('data-previo-lang')||'cs',currency:c.getAttribute('data-previo-currency')||'CZK'};var l=document.createElement('script');l.src='https://booking.previo.app/loader/';document.head.appendChild(l);var o=new MutationObserver(function(){var f=c.querySelector('iframe');if(!f)return;o.disconnect();window.addEventListener('message',function(e){if(!/^https:\/\/([a-z0-9-]+\.)*previo\.app$/.test(e.origin))return;var d=e.data,h=null;if(typeof d==='object'&&d!==null){h=d.height||d.frameHeight||d.iframeHeight||null}else if(typeof d==='string'){try{var p=JSON.parse(d);h=p.height||p.frameHeight||null}catch(err){}}if(h&&+h>50){f.style.height=(+h)+'px'}})});o.observe(c,{childList:true,subtree:true})})();